def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def norm_pos(p):
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return p[0], p[1]
        return None

    def get_int(key, default=0):
        v = observation.get(key, default)
        return v if isinstance(v, int) else default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, tgt):
        return [clamp_step(tgt[0] - src[0]), clamp_step(tgt[1] - src[1])]

    def step_away(src, tgt):
        return [clamp_step(src[0] - tgt[0]), clamp_step(src[1] - tgt[1])]

    def best_by(items, key_fn, pick_min=True):
        best_item = None
        best_val = None
        for it in items:
            try:
                val = key_fn(it)
            except Exception:
                continue
            if best_item is None or (pick_min and val < best_val) or ((not pick_min) and val > best_val):
                best_item = it
                best_val = val
        return best_item

    env = observation.get("environment_name", "resource_collection")
    self_pos = norm_pos(observation.get("self_position")) or (0, 0)
    opp_pos = norm_pos(observation.get("opponent_position")) or self_pos
    gw = get_int("grid_width", 0)
    gh = get_int("grid_height", 0)
    role = observation.get("self_role", "pursuer")

    # Immediate threat handling
    if dist(self_pos, opp_pos) <= 1:
        away = step_away(self_pos, opp_pos)
        if away != [0, 0]:
            return away

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = best_by(corners, lambda c: dist(c, opp_pos), pick_min=False)
        if target is None:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = best_by([norm_pos(p) for p in targets if norm_pos(p) is not None], lambda p: dist(self_pos, p), pick_min=True)
        if target is not None:
            return step_toward(self_pos, target)
        # fallback: move toward center or pressure opponent
        center = (gw // 2, gh // 2) if gw and gh else opp_pos
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    res_list = [norm_pos(p) for p in resources if norm_pos(p) is not None]
    if res_list:
        # prefer resource we can reach before opponent; tie-break by closeness to self
        def score(p):
            return (dist(self_pos, p), dist(opp_pos, p))
        target = best_by(res_list, score, pick_min=True)
        if target is not None:
            return step_toward(self_pos, target)

    # Denial / fallback: move toward opponent if nothing else, otherwise center
    if resources:
        block = best_by(res_list, lambda p: dist(opp_pos, p), pick_min=True)
        if block is not None:
            return step_toward(self_pos, block)
    center = (gw // 2, gh // 2) if gw and gh else opp_pos
    return step_toward(self_pos, center)

